package br.com.admeclesial.interfaces.web.sacramento;
import br.com.admeclesial.application.organizacao.OrganizacaoEclesialApplicationService; import br.com.admeclesial.application.sacramento.*; import br.com.admeclesial.domain.sacramento.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.util.*;
@Controller @RequestMapping("/sacramentos") public class SacramentoWebController {
 private final SacramentoApplicationService service; private final OrganizacaoEclesialApplicationService organizacaoService;
 public SacramentoWebController(SacramentoApplicationService s,OrganizacaoEclesialApplicationService o){service=s;organizacaoService=o;}
 @GetMapping public String lista(Model m){m.addAttribute("sacramentos",service.listar());return "sacramento/lista";}
 @GetMapping("/novo") public String novo(Model m){m.addAttribute("request",new SacramentoRequest(null,null,null,null,null,null));m.addAttribute("organizacoes",organizacaoService.listar().stream().filter(x->x.ativo()).toList());m.addAttribute("tipos",TipoSacramento.values());m.addAttribute("status",StatusSacramento.values());return "sacramento/form";}
 @PostMapping public String criar(@ModelAttribute("request") SacramentoRequest r,Model m){try{var e=service.criar(r);return "redirect:/sacramentos/"+e.uuid();}catch(SacramentoBusinessException ex){m.addAttribute("businessError",ex.getMessage());preencher(m,r);return "sacramento/form";}}
 @GetMapping("/{uuid}") public String detalhe(@PathVariable UUID uuid,Model m){m.addAttribute("sacramento",service.buscar(uuid));return "sacramento/detalhe";}
 @GetMapping("/{uuid}/editar") public String editar(@PathVariable UUID uuid,Model m){var e=service.buscar(uuid);m.addAttribute("request",new SacramentoRequest(e.organizacaoEclesialUuid(),e.tipo(),e.dataCelebracao(),e.local(),e.status(),e.observacao()));m.addAttribute("sacramentoUuid",uuid);m.addAttribute("organizacoes",organizacaoService.listar().stream().filter(x->x.ativo()).toList());m.addAttribute("tipos",TipoSacramento.values());m.addAttribute("status",StatusSacramento.values());return "sacramento/form";}
 @PostMapping("/{uuid}") public String atualizar(@PathVariable UUID uuid,@ModelAttribute("request") SacramentoRequest r,Model m){try{service.atualizar(uuid,r);return "redirect:/sacramentos/"+uuid;}catch(SacramentoBusinessException ex){m.addAttribute("businessError",ex.getMessage());m.addAttribute("sacramentoUuid",uuid);preencher(m,r);return "sacramento/form";}}
 private void preencher(Model m,SacramentoRequest r){m.addAttribute("organizacoes",organizacaoService.listar().stream().filter(x->x.ativo()).toList());m.addAttribute("tipos",TipoSacramento.values());m.addAttribute("status",StatusSacramento.values());}
}
